<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\{Sale,Stock,Department,PharmacySetting};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DashboardController extends Controller {
 public function index(Request $r){$low=PharmacySetting::valueFor('low_stock_threshold',20);$days=PharmacySetting::valueFor('expiry_warning_days',30);$period=$r->query('period','daily');$start=match($period){'weekly'=>now()->startOfWeek(),'monthly'=>now()->startOfMonth(),default=>now()->startOfDay()};$sales=Sale::where('sold_at','>=',$start);if(!in_array($r->user()->role,['hod','md'],true))$sales->where('department_id',$r->user()->department_id);$total=(clone $sales)->sum('total_naira');$monthSales=Sale::whereMonth('sold_at',now()->month)->whereYear('sold_at',now()->year);if(!in_array($r->user()->role,['hod','md'],true))$monthSales->where('department_id',$r->user()->department_id);$month=$monthSales->sum('total_naira');$stockValue=Stock::selectRaw('SUM(quantity * cost_price_naira) as value')->value('value')??0;$monthChart=Sale::where('sold_at','>=',now()->startOfMonth());if(!in_array($r->user()->role,['hod','md'],true))$monthChart->where('department_id',$r->user()->department_id);return response()->json(['period'=>$period,'today_sales_naira'=>$total,'month_sales_naira'=>$month,'stock_value_naira'=>(int)$stockValue,'departments'=>Department::where('is_active',true)->count(),'department_performance'=>(clone $sales)->select('department_id',DB::raw('SUM(total_naira) total_naira'))->groupBy('department_id')->with('department:id,name')->get(),'staff_performance'=>(clone $sales)->select('staff_id',DB::raw('SUM(total_naira) total_naira'),DB::raw('COUNT(*) transactions'))->groupBy('staff_id')->with('staff:id,name')->orderByDesc('total_naira')->limit(10)->get(),'sales_chart'=>$monthChart->selectRaw('DATE(sold_at) date, SUM(total_naira) total_naira')->groupByRaw('DATE(sold_at)')->orderBy('date')->get(),'recent_sales'=>Sale::with(['patient','department','staff'])->latest('sold_at')->limit(8)->get(),'low_stock_count'=>Stock::where('quantity','<',$low)->count(),'expiring_count'=>Stock::whereBetween('expiry_date',[now()->toDateString(),now()->addDays($days)->toDateString()])->count(),'low_stock_threshold'=>$low,'expiry_warning_days'=>$days]);}
 public function reports(Request $r){$period=$r->query('period','daily');$from=$r->query('from',match($period){'weekly'=>now()->startOfWeek()->toDateString(),'monthly'=>now()->startOfMonth()->toDateString(),default=>now()->toDateString()});$to=$r->query('to',now()->toDateString());$sales=Sale::whereBetween('sold_at',[$from.' 00:00:00',$to.' 23:59:59']);return response()->json(['from'=>$from,'to'=>$to,'total_naira'=>(int)(clone $sales)->sum('total_naira'),'discount_naira'=>(int)(clone $sales)->sum('discount_naira'),'transaction_count'=>(clone $sales)->count(),'payment_modes'=>(clone $sales)->select('payment_mode',DB::raw('SUM(total_naira) total_naira'),DB::raw('COUNT(*) count'))->groupBy('payment_mode')->get(),'departments'=>(clone $sales)->select('department_id',DB::raw('SUM(total_naira) total_naira'))->groupBy('department_id')->with('department:id,name')->get(),'staff'=>(clone $sales)->select('staff_id',DB::raw('SUM(total_naira) total_naira'),DB::raw('COUNT(*) transactions'))->groupBy('staff_id')->with('staff:id,name')->orderByDesc('total_naira')->get(),'daily'=>(clone $sales)->selectRaw('DATE(sold_at) date, SUM(total_naira) total_naira, COUNT(*) transactions')->groupByRaw('DATE(sold_at)')->orderBy('date')->get()]);}
}
